// RatingStars.jsx
export function RatingStars({ value, max = 5, onRate }) {
  const stars = Array.from({ length: max }, (_, i) => i + 1);

  return (
    <div className="rating">
      {stars.map((n) => (
        <button
          key={n}
          type="button"
          aria-label={`Oceń na ${n} z ${max}`}
          onClick={() => onRate(n)}
        >
          {n <= value ? '★' : '☆'}
        </button>
      ))}
    </div>
  );
}

